<?php if(!$wingTimeline): ?><p class="text-secondary mb-0">No wing participation has been recorded.</p><?php else: ?><ol class="wing-timeline">
<?php foreach($wingTimeline as $entry): ?><li><div class="wing-timeline-heading"><strong><?= e(\App\Membership\WingService::WINGS[$entry['wing_code']]) ?></strong><span class="badge <?= $entry['ended_on']?'bg-secondary':'bg-success' ?>"><?= $entry['ended_on']?'Ended':'Enrolled' ?></span></div><p class="wing-timeline-dates"><?= e(date_display($entry['joined_on'])) ?> &mdash; <?= $entry['ended_on']?e(date_display($entry['ended_on'])):'Present' ?></p><p class="small text-secondary mb-2"><?= e($entry['member_name_snapshot']) ?> &middot; Sys No. <?= e($entry['member_number_snapshot']) ?> &middot; Enrollment #<?= e($entry['id']) ?></p><div class="wing-timeline-audit"><span>Recorded by <?= e($entry['enrolled_by']??'Staff') ?> on <?= e(date_display($entry['created_at'],true)) ?> UTC</span><?php if($entry['ended_on']): ?><span><?= $entry['end_reason']==='membership_removed'?'Party membership removed':'Left wing' ?> &middot; Ended by <?= e($entry['ended_by']??'Staff') ?> &middot; Recorded <?= e(date_display($entry['updated_at'],true)) ?> UTC</span><?php endif; ?></div></li><?php endforeach; ?>
</ol><?php endif; ?>
